const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,d=3)=>Number(v).toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d});
export function recipeMarkup(milling,{original=false,sourceUrl='data/milling-recipes.json'}={}){
 const p=milling.recipe;if(!p)return '';
 const changed=milling.operations.some((o,i)=>{const l=p.legs[i];return o.flutes!==l.flutes||o.rpm!==l.rpm||o.feedMmMin!==l.feed_mm_min||o.axialDepthMm!==l.axial_depth_mm||o.radialEngagementMm!==l.radial_engagement_mm;});
 const tools=[...new Map(p.legs.map(l=>[l.catalogueEDP,l])).values()];
 return `<div class="recipe-panel"><div class="recipe-heading"><div><span class="section-number">CNC TOOL RECOMMENDATION</span><h4>Recommended milling recipe</h4></div><span class="tag">${p.distinctTools} cutter${p.distinctTools===1?'':'s'} · ${p.machiningFaces} machining face${p.machiningFaces===1?'':'s'}</span></div><p>${original?'The original nominal case uses the following recipe.':changed?'The source-derived tool selection is retained; the cutting conditions below include your edits.':'The retained carbon-payback recipe is applied to this opening geometry.'} ${p.distinctTools===1?'The selected cutter performs both roughing and finishing.':'A broad cutter removes the accessible bulk; a smaller long-neck cutter finishes the remaining walls and corners.'}</p><div class="recipe-tools">${tools.map(t=>`<div><strong>Ø ${f(t.diameter_mm,1)} mm · OSG ${t.neckReachMm?'WXL-LN-EMS':'WXL-EMS'}</strong><span>Reference EDP ${esc(t.catalogueEDP)} · ${t.flutes} flutes · ${f(t.fluteLengthMm,1)} mm flute length${t.neckReachMm?' · '+f(t.neckReachMm,1)+' mm neck reach':''}</span></div>`).join('')}</div><div class="table-scroll"><table><caption>Applied operations · all openings combined</caption><thead><tr>${['Operation','Cutter (mm)','Flutes','Removed volume (%)','Speed (rpm)','Feed (mm/min)','Axial depth (mm)','Radial engagement (mm)','Time (min)','Step electricity (kWh)'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${milling.operations.map(o=>'<tr>'+[o.operation,f(o.diameterMm,1),o.flutes,f(100*o.volumeFraction,2),f(o.rpm,0),f(o.feedMmMin,1),f(o.axialDepthMm,4),f(o.radialEngagementMm,4),f(o.activeMinutes,2),f(o.driveElectricityKWh+o.baseElectricityKWh,4)].map(v=>`<td>${esc(v)}</td>`).join('')+'</tr>').join('')}</tbody></table></div><p class="recipe-energy">Step electricity includes cutting-drive work and machine base power during that step.${milling.basePowerKW!==undefined?' Applied base power: '+f(milling.basePowerKW,2)+' kW; drive efficiency: '+f(100*milling.driveEfficiency,1)+'%; non-cutting time: '+f(milling.noncutMinutesPerSetup,2)+' min per allocated setup; chip-press feed: '+f(milling.chipPressFeedKgH,2)+' kg/h.':''} Allocated non-cutting electricity: <strong>${f(milling.noncutElectricityKWh,4)} kWh</strong>; added chip-press electricity: <strong>${f(milling.chipPressElectricityKWh,4)} kWh</strong>. Total added electricity: <strong>${f(milling.siteElectricityKWh,4)} kWh</strong>.</p><p class="form-note">${milling.allocatedSetupCount??p.setupCount} allocated setup${(milling.allocatedSetupCount??p.setupCount)===1?'':'s'}. Finishing time includes the retained contour-travel minimum where applicable. Cutter access and reach follow the retained planning screens; the final CAM programme, holder clearance and shop conditions require verification. <a href="${esc(p.catalogueUrl)}" target="_blank" rel="noopener">Read the OSG catalogue</a> · <a href="${esc(sourceUrl)}" download>Download the complete recipe and source checks</a>.</p></div>`;
}
